/**
 * Tests for pushed session titles (src/services/sessionEvents.ts, the emit in
 * src/services/history.ts, the RENAME_SESSION reducer case, and the wire
 * contract between them).
 *
 * WHY this exists: a new conversation is created as "New chat", and its real
 * title is generated by an LLM in the *background* — after the chat SSE stream
 * has already closed. The client used to learn titles only from
 * `GET /api/sessions`, refreshed once at turn end plus once on a hard-coded 2s
 * timer. Whenever title generation took longer than that the write landed with
 * no reader left, so the sidebar and the browser tab kept the placeholder
 * until the user pressed F5.
 *
 * The fix is a push: `renameSession()` emits on a process-global bus, the
 * `GET /api/sessions/events` SSE route forwards it, and the client patches the
 * one row it names. The checks below guard each link in that chain — in
 * particular that `renameSession` still announces itself, because that emit is
 * the single point every rename path (fallback title, LLM upgrade, `/title`)
 * funnels through, and losing it would silently restore the F5 bug.
 *
 * ISOLATION: `DB_PATH` is `process.cwd()`-relative, so this script chdirs into
 * a fresh `mkdtemp` BEFORE importing the store (see
 * `recent-files-store.test.mjs` for the same trick). Importing first would
 * open and mutate the checkout's real ./locopilot.db.
 */

import { afterAll, beforeAll, describe, expect, jest, test } from '@jest/globals';
import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

/** Resolves a repo-relative module against this script, not against the cwd. */
const here = path.dirname(fileURLToPath(import.meta.url));
const moduleUrl = (relative) => pathToFileURL(path.join(here, relative)).href;

const root = mkdtempSync(path.join(tmpdir(), 'locopilot-session-title-push-'));
const previousCwd = process.cwd();

let createSession;
let renameSession;
let emitSessionEvent;
let subscribeSessionEvents;
let chatReducer;
let initialState;
let parseRenameEvent;
let SESSIONS_SSE_EVENT_NAME;

beforeAll(async () => {
  // Must precede the import: `history.ts` builds `DB_PATH` at module load.
  process.chdir(root);

  ({ createSession, renameSession } = await import(moduleUrl('../src/services/history.ts')));
  ({ emitSessionEvent, subscribeSessionEvents } = await import(
    moduleUrl('../src/services/sessionEvents.ts')
  ));
  ({ chatReducer, initialState } = await import(moduleUrl('../src/app/lib/chatStore.ts')));
  ({ parseRenameEvent } = await import(moduleUrl('../src/app/hooks/useSessionEvents.ts')));
  ({ SESSIONS_SSE_EVENT_NAME } = await import(moduleUrl('../src/services/sseNames.ts')));
});

afterAll(() => {
  // Restore the cwd before removing the scratch root (Windows keeps the
  // directory busy while it is the cwd) and never leave the DB behind.
  process.chdir(previousCwd);
  rmSync(root, { recursive: true, force: true });
});

/** Collects events from the bus for the duration of one test. */
function capture() {
  const events = [];
  const unsubscribe = subscribeSessionEvents((event) => events.push(event));
  return { events, unsubscribe };
}

describe('the rename bus', () => {
  test('renameSession announces the new title', () => {
    const sessionId = createSession('New chat', 'test-model');
    const { events, unsubscribe } = capture();

    try {
      renameSession(sessionId, '👋 Greeting Exchange');
    } finally {
      unsubscribe();
    }

    expect(events).toEqual([{ kind: 'renamed', sessionId, name: '👋 Greeting Exchange' }]);
  });

  test('unsubscribing stops delivery', () => {
    const sessionId = createSession('New chat', 'test-model');
    const { events, unsubscribe } = capture();
    unsubscribe();

    renameSession(sessionId, '👋 After Unsubscribe');

    expect(events).toEqual([]);
  });

  test('a throwing subscriber cannot break the rename or the other subscribers', () => {
    const sessionId = createSession('New chat', 'test-model');
    const { events, unsubscribe } = capture();
    const unsubscribeBad = subscribeSessionEvents(() => {
      throw new Error('this listener is broken');
    });
    // The emit deliberately reports the failure; keep the run output readable.
    const errorSpy = jest.spyOn(console, 'error').mockImplementation(() => {});

    try {
      // Emitting is part of the write path: it must never throw, or a dying
      // SSE stream could take the title write down with it.
      expect(() => renameSession(sessionId, '👋 Survives A Bad Listener')).not.toThrow();
      expect(errorSpy).toHaveBeenCalledWith(
        '[session-events] listener threw: this listener is broken'
      );
    } finally {
      errorSpy.mockRestore();
      unsubscribeBad();
      unsubscribe();
    }

    expect(events).toEqual([{ kind: 'renamed', sessionId, name: '👋 Survives A Bad Listener' }]);
  });

  test('the bus is pinned to globalThis so a second module instance still receives', async () => {
    // Next.js can evaluate this module more than once (dev HMR, separate
    // route-handler registries). If the listener set lived in module scope
    // instead of on globalThis, the chat route would emit into one bus while
    // the SSE route listened on another and every title would vanish again.
    const secondInstance = await import(`${moduleUrl('../src/services/sessionEvents.ts')}?clone=1`);
    expect(secondInstance).not.toBe(await import(moduleUrl('../src/services/sessionEvents.ts')));

    const events = [];
    const unsubscribe = secondInstance.subscribeSessionEvents((event) => events.push(event));

    try {
      emitSessionEvent({ kind: 'renamed', sessionId: 4242, name: '👋 Shared Bus' });
    } finally {
      unsubscribe();
    }

    expect(events).toEqual([{ kind: 'renamed', sessionId: 4242, name: '👋 Shared Bus' }]);
  });
});

describe('the RENAME_SESSION reducer case', () => {
  const session = (id, name) => ({
    id,
    name,
    model: 'test-model',
    created_at: '2026-01-01 00:00:00',
    updated_at: '2026-01-01 00:00:00',
    last_prompt_eval_count: null,
    last_eval_count: null,
    last_total_tokens: null,
  });

  const stateWithTwo = () => ({
    ...initialState,
    sessions: [session(1, '👋 Older Chat'), session(2, 'New chat')],
  });

  test('patches only the named session', () => {
    const before = stateWithTwo();
    const after = chatReducer(before, {
      type: 'RENAME_SESSION',
      sessionId: 2,
      name: '👋 Greeting Exchange',
    });

    expect(after.sessions[1].name).toBe('👋 Greeting Exchange');
    // The untouched row keeps its identity, so its components can memo-skip.
    expect(after.sessions[0]).toBe(before.sessions[0]);
    // A new array is what wakes `document.title` up (it resolves the title
    // from `state.sessions`).
    expect(after.sessions).not.toBe(before.sessions);
  });

  test('an unknown session is ignored rather than appended', () => {
    const before = stateWithTwo();
    const after = chatReducer(before, {
      type: 'RENAME_SESSION',
      sessionId: 99,
      name: '👋 Not In The List',
    });

    expect(after).toBe(before);
    expect(after.sessions).toHaveLength(2);
  });

  test('an unchanged title returns the same state (no pointless re-render)', () => {
    const before = stateWithTwo();
    const after = chatReducer(before, {
      type: 'RENAME_SESSION',
      sessionId: 2,
      name: 'New chat',
    });

    expect(after).toBe(before);
  });
});

describe('the SSE wire contract', () => {
  test('the frame the route writes is what the client parses', () => {
    // The route writes `event: <name>\ndata: <json>`; the hook listens for the
    // name and parses the json. Nothing shares a type across that boundary, so
    // this pins both halves together.
    expect(SESSIONS_SSE_EVENT_NAME).toBe('session-renamed');

    const event = { kind: 'renamed', sessionId: 29, name: '👋 Greeting Exchange' };
    const frame = `event: ${SESSIONS_SSE_EVENT_NAME}\ndata: ${JSON.stringify(event)}\n\n`;
    const [eventLine, dataLine] = frame.split('\n');

    expect(eventLine).toBe('event: session-renamed');
    expect(dataLine.startsWith('data: ')).toBe(true);
    expect(parseRenameEvent(dataLine.slice('data: '.length))).toEqual({
      sessionId: 29,
      name: '👋 Greeting Exchange',
    });
  });

  test('malformed and foreign frames are dropped, not dispatched', () => {
    expect(parseRenameEvent('not json')).toBeNull();
    expect(parseRenameEvent('{"kind":"renamed"}')).toBeNull();
    expect(parseRenameEvent('{"kind":"renamed","sessionId":"29","name":"x"}')).toBeNull();
    expect(parseRenameEvent('{"kind":"something-else","sessionId":29,"name":"x"}')).toBeNull();
  });
});
